module adaptive_aero_history_store (
    input         clk,
    input         reset_n,
    input  [8:0] cfg_history_base,
    input  [7:0] cfg_payload_base,
    output reg    history_busy,
    output reg    payload_busy
);

reg [127:0] mem [0:511];
reg [8:0] rd_addr;
reg [8:0] wr_addr;
reg [127:0] rd_data;

always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        history_busy <= 1'b0;
        payload_busy <= 1'b0;
        rd_addr <= 9'd0;
        wr_addr <= 9'd0;
        rd_data <= 128'd0;
    end else begin
        history_busy <= 1'b0;
        payload_busy <= 1'b0;
        rd_addr <= cfg_history_base;
        wr_addr <= {cfg_payload_base[6:0], 2'b00};
        mem[wr_addr] <= {103'd0, cfg_history_base, cfg_payload_base};
        rd_data <= mem[rd_addr];
    end
end

endmodule

module adaptive_aero_safety_bounding (
    input         clk,
    input         reset_n,
    input         cfg_enable,
    input         cfg_clear_fault,
    input  [7:0] cfg_tilt_limit,
    input  [7:0] cfg_deflection_limit,
    input         validation_valid,
    input         validation_error,
    input  [7:0] validation_delta_code,
    input  [7:0] surrogate_tilt_cmd,
    input  [7:0] surrogate_deflection_cmd,
    input  [7:0] reference_tilt_cmd,
    input  [7:0] reference_deflection_cmd,
    output reg    actuator_cmd_valid,
    output reg [7:0] actuator_cmd_tilt,
    output reg [7:0] actuator_cmd_deflection,
    output reg [1:0] actuator_cmd_mode,
    output reg    fault_latched,
    output reg    status_valid,
    output reg [7:0] status_code,
    output reg    status_fault_latched,
    output reg    status_timeout_active,
    output reg    status_stale_active
);

wire [7:0] tilt_bounded;
wire [7:0] defl_bounded;
wire [7:0] validation_mix;

assign tilt_bounded = (surrogate_tilt_cmd > cfg_tilt_limit) ? cfg_tilt_limit : surrogate_tilt_cmd;
assign defl_bounded = (surrogate_deflection_cmd > cfg_deflection_limit) ? cfg_deflection_limit : surrogate_deflection_cmd;
assign validation_mix = validation_delta_code ^ reference_tilt_cmd ^ reference_deflection_cmd;

always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        actuator_cmd_valid <= 1'b0;
        actuator_cmd_tilt <= 8'd0;
        actuator_cmd_deflection <= 8'd0;
        actuator_cmd_mode <= 2'b00;
        fault_latched <= 1'b0;
        status_valid <= 1'b0;
        status_code <= 8'd0;
        status_fault_latched <= 1'b0;
        status_timeout_active <= 1'b0;
        status_stale_active <= 1'b0;
    end else begin
        status_fault_latched <= fault_latched;
        status_timeout_active <= validation_error;
        status_stale_active <= ~validation_valid;
        if (cfg_clear_fault) fault_latched <= 1'b0;
        if (validation_error || !validation_valid || !cfg_enable) begin
            actuator_cmd_valid <= 1'b0;
            fault_latched <= fault_latched | validation_error | ~cfg_enable;
            status_valid <= 1'b0;
            status_code <= validation_mix;
        end else begin
            actuator_cmd_valid <= 1'b1;
            actuator_cmd_tilt <= tilt_bounded;
            actuator_cmd_deflection <= defl_bounded;
            actuator_cmd_mode <= 2'b01;
            status_valid <= 1'b1;
            status_code <= validation_mix;
        end
    end
end

endmodule

module adaptive_aero_surrogate_reference (
    input         clk,
    input         reset_n,
    input         cfg_enable,
    input  [1:0] cfg_mode_select,
    input  [7:0] cfg_tilt_limit,
    input  [7:0] cfg_deflection_limit,
    input         response_valid,
    input  [127:0] response_data,
    input         response_stale,
    output reg [31:0] pack_vehicle_state,
    output reg [15:0] pack_wind_state,
    output reg [15:0] pack_reference_state,
    output reg [7:0] surrogate_tilt_cmd,
    output reg [7:0] surrogate_deflection_cmd,
    output reg [7:0] reference_tilt_cmd,
    output reg [7:0] reference_deflection_cmd,
    output reg        validation_valid,
    output reg        validation_error,
    output reg [7:0] validation_delta_code
);

reg [7:0] resp_tilt;
reg [7:0] resp_defl;
reg [7:0] ref_tilt_calc;
reg [7:0] ref_defl_calc;
reg [7:0] delta_tilt;
reg [7:0] delta_defl;

always @(*) begin
    resp_tilt = response_data[7:0];
    resp_defl = response_data[15:8];
    ref_tilt_calc = cfg_tilt_limit;
    ref_defl_calc = cfg_deflection_limit;
    delta_tilt = (resp_tilt > ref_tilt_calc) ? (resp_tilt - ref_tilt_calc) : (ref_tilt_calc - resp_tilt);
    delta_defl = (resp_defl > ref_defl_calc) ? (resp_defl - ref_defl_calc) : (ref_defl_calc - resp_defl);
end

always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        pack_vehicle_state <= 32'd0;
        pack_wind_state <= 16'd0;
        pack_reference_state <= 16'd0;
        surrogate_tilt_cmd <= 8'd0;
        surrogate_deflection_cmd <= 8'd0;
        reference_tilt_cmd <= 8'd0;
        reference_deflection_cmd <= 8'd0;
        validation_valid <= 1'b0;
        validation_error <= 1'b0;
        validation_delta_code <= 8'd0;
    end else begin
        pack_vehicle_state <= response_data[31:0];
        pack_wind_state <= response_data[47:32];
        pack_reference_state <= response_data[63:48];
        surrogate_tilt_cmd <= response_data[7:0];
        surrogate_deflection_cmd <= response_data[15:8];
        reference_tilt_cmd <= cfg_tilt_limit;
        reference_deflection_cmd <= cfg_deflection_limit;
        validation_valid <= cfg_enable && response_valid && !response_stale && (delta_tilt <= cfg_tilt_limit) && (delta_defl <= cfg_deflection_limit);
        validation_error <= response_stale || (response_valid && ((delta_tilt > cfg_tilt_limit) || (delta_defl > cfg_deflection_limit) || (cfg_mode_select == 2'b11)));
        validation_delta_code <= delta_tilt | delta_defl;
    end
end

endmodule

module adaptive_aero_transport (
    input         clk,
    input         reset_n,
    input         cfg_enable,
    input         cfg_surrogate_select,
    input         model_req_ready,
    output reg    model_req_valid,
    output reg [63:0] model_req_data,
    input         model_rsp_valid,
    input  [127:0] model_rsp_data,
    output reg    model_rsp_ready,
    input  [31:0] pack_vehicle_state,
    input  [15:0] pack_wind_state,
    input  [15:0] pack_reference_state,
    output reg    request_busy,
    output reg    response_valid,
    output reg [127:0] response_data,
    output reg    response_stale
);

reg [3:0] age_cnt;

always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        model_req_valid <= 1'b0;
        model_req_data <= 64'd0;
        model_rsp_ready <= 1'b0;
        request_busy <= 1'b0;
        response_valid <= 1'b0;
        response_data <= 128'd0;
        response_stale <= 1'b0;
        age_cnt <= 4'd0;
    end else begin
        model_rsp_ready <= cfg_enable;
        response_valid <= 1'b0;
        response_stale <= 1'b0;
        if (cfg_enable) begin
            model_req_data <= {pack_vehicle_state[31:0], pack_wind_state[15:0], pack_reference_state[15:0]};
            model_req_valid <= 1'b1;
            request_busy <= ~model_req_ready;
            if (model_req_ready) begin
                request_busy <= 1'b0;
            end
            if (model_rsp_valid) begin
                response_valid <= 1'b1;
                response_data <= model_rsp_data;
                age_cnt <= 4'd0;
            end else if (request_busy) begin
                if (age_cnt != 4'hf) age_cnt <= age_cnt + 4'd1;
                if (age_cnt >= 4'd3) response_stale <= 1'b1;
            end
        end else begin
            model_req_valid <= 1'b0;
            request_busy <= 1'b0;
            age_cnt <= 4'd0;
        end
    end
end

endmodule
